import json
from dataclasses import dataclass, asdict
from typing import Any, Dict

@dataclass
class EventMessage:
    event_id: str
    event_type: str
    data: Dict[str, Any]
    source: str
    timestamp: str

    def to_json(self) -> str:
        return json.dumps(asdict(self))

    @classmethod
    def from_json(cls, json_str: str):
        return cls(**json.loads(json_str))

import os
from azure.servicebus import ServiceBusClient

class MessagingClient:
    def __init__(self, connection_str: str, queue_name: str | None = None, topic_name: str | None = None, subscription_name: str | None = None):
        self.connection_str = connection_str
        self.queue_name = queue_name
        self.topic_name = topic_name
        self.subscription_name = subscription_name
        self.client = ServiceBusClient.from_connection_string(self.connection_str)

    def get_sender(self):
        if self.topic_name:
            return self.client.get_topic_sender(topic_name=self.topic_name)
        elif self.queue_name:
            return self.client.get_queue_sender(queue_name=self.queue_name)
        else:
            raise ValueError("Either queue_name or topic_name must be provided for sender.")

    def get_receiver(self):
        if self.queue_name:
            return self.client.get_queue_receiver(queue_name=self.queue_name)
        elif self.topic_name and self.subscription_name:
            return self.client.get_subscription_receiver(topic_name=self.topic_name, subscription_name=self.subscription_name)
        else:
            raise ValueError("Either queue_name or topic_name with subscription_name must be provided for receiver.")

    def close(self):
        self.client.close()

def get_service_bus_client(queue_name: str | None = None, topic_name: str | None = None, subscription_name: str | None = None) -> MessagingClient:
    connection_str = os.environ.get("AZURE_SERVICE_BUS_CONNECTION_STRING")
    if not connection_str:
        raise ValueError("AZURE_SERVICE_BUS_CONNECTION_STRING environment variable not set.")
    return MessagingClient(connection_str, queue_name, topic_name, subscription_name)

import os
import openai
from openai import OpenAI
from messaging_models import EventMessage

def check_message_safety(event_message: EventMessage) -> dict:
    # Ensure OPENAI_API_KEY is set in environment variables
    api_key = os.environ.get("OPENAI_API_KEY")
    if not api_key:
        raise ValueError("OPENAI_API_KEY environment variable not set.")

    client = OpenAI(api_key=api_key)

    # Assuming the message payload has a 'text' key or similar for content to check
    text_to_check = event_message.data.get("message_content", str(event_message.data))

    print(f"Checking safety for text: {text_to_check[:100]}...")

    try:
        response = client.moderations.create(input=text_to_check)
        moderation_result = response.results[0]

        print(f"Moderation flagged: {moderation_result.flagged}")
        if moderation_result.flagged:
            print("Categories flagged:")
            for category, is_flagged in moderation_result.categories.items():
                if is_flagged:
                    print(f"  - {category}: {is_flagged} (score: {moderation_result.category_scores[category]:.4f})")
        return moderation_result.model_dump()
    except openai.APIError as e:
        print(f"OpenAI API error: {e}")
        return {"error": str(e), "flagged": True}
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
        return {"error": str(e), "flagged": True}

if __name__ == "__main__":
    # Example usage with a dummy EventMessage
    from datetime import datetime
    sample_event_safe = EventMessage(
        event_id="safe-123",
        event_type="content.check",
        data={
            "user_id": "user_def",
            "message_content": "This is a perfectly safe message about puppies and rainbows.",
            "timestamp": datetime.utcnow().isoformat()
        },
        source="test_safety_app",
        timestamp=datetime.utcnow().isoformat()
    )

    sample_event_unsafe = EventMessage(
        event_id="unsafe-456",
        event_type="content.check",
        data={
            "user_id": "user_ghi",
            "message_content": "I hate you! You are a terrible person!",
            "timestamp": datetime.utcnow().isoformat()
        },
        source="test_safety_app",
        timestamp=datetime.utcnow().isoformat()
    )

    print("\n--- Checking Safe Event ---")
    check_message_safety(sample_event_safe)

    print("\n--- Checking Unsafe Event ---")
    check_message_safety(sample_event_unsafe)
